Trim the text, reject an empty string, then use Number so the whole string has to be a number. Anything the engine cannot read becomes null instead of NaN.

code:
function safeParseInt(str) {
  const text = String(str).trim();
  if (text === '') return null;
  const value = Number(text);
  return Number.isFinite(value) ? Math.trunc(value) : null;
}
const inputs = ['12px', ' 7 ', '1e3', '', '42', 'abc'];
const results = inputs.map((value) => String(safeParseInt(value)));
console.log(results.join(' | ')); // null | 7 | 1000 | null | 42 | null
console.log(safeParseInt('8.9')); // 8

output:
null | 7 | 1000 | null | 42 | null
8

Handle text separately from other types, because the text 'false' is a long non-empty string and would be truthy on its own.

code:
function toBool(value) {
  if (typeof value === 'string') {
    const text = value.trim().toLowerCase();
    return !['', 'false', '0', 'null', 'undefined'].includes(text);
  }
  return Boolean(value);
}
const inputs = ['', 'false', 'TRUE', '0', 0, 1, null, undefined, 'yes'];
console.log(inputs.map((value) => String(toBool(value))).join(',')); // false,false,true,false,false,true,false,false,true

output:
false,false,true,false,false,true,false,false,true

Convert one value at a time and test it with Number.isFinite, so one bad entry cannot poison the whole total.

code:
function sumAsNumbers(list) {
  let total = 0;
  for (const value of list) {
    const num = Number(value);
    if (Number.isFinite(num)) total += num;
  }
  return total;
}
console.log(sumAsNumbers(['10', 20, 'abc', '5.5'])); // 35.5
console.log(sumAsNumbers(['10', 20, 'abc', '5.5']).toFixed(2)); // 35.50

output:
35.5
35.50

parseFloat keeps going until a character stops making sense, so a trailing unit or word is ignored rather than rejected.

code:
function parseNumber(text) {
  const value = parseFloat(text);
  return Number.isNaN(value) ? 'NaN' : value;
}
console.log(['3.14abc', '42', '1e3', 'abc'].map(parseNumber).join(' | ')); // 3.14 | 42 | 1000 | NaN

output:
3.14 | 42 | 1000 | NaN

Zero is a real value, so the nullish operator keeps it while the OR operator throws it away. That difference is the whole point of the pair.

code:
function withNullish(value) {
  return value ?? 'default';
}
function withOr(value) {
  return value || 'default';
}
console.log([0, null, 7].map(withNullish).join(',')); // 0,default,7
console.log([0, null, 7].map(withOr).join(',')); // default,default,7

output:
0,default,7
default,default,7

Split on the ampersand and the equals sign, then try Number on each value and keep it only when the whole value converted cleanly.

code:
function parseQuery(query) {
  const result = {};
  for (const pair of query.split('&')) {
    const [key, value] = pair.split('=');
    const num = Number(value);
    result[key] = value !== '' && Number.isFinite(num) ? num : value;
  }
  return result;
}
console.log(JSON.stringify(parseQuery('a=1&b=2&c=hello'))); // {"a":1,"b":2,"c":"hello"}

output:
{"a":1,"b":2,"c":"hello"}

Multiplying by 100, rounding and dividing by 100 is the classic trick, but a value such as 2.675 is stored just below 2.675 in binary, so the rounding lands on 2.68.

code:
function roundTo2(n) {
  return Math.round(n * 100) / 100;
}
console.log(roundTo2(1.005), roundTo2(2.675)); // 1 2.68
console.log(roundTo2(1.005).toFixed(2), roundTo2(2.675).toFixed(2)); // 1.00 2.68

output:
1 2.68
1.00 2.68

Convert first so a text value cannot slip past the comparisons, then clamp with two Math calls.

code:
function clampPercent(value) {
  const num = Number(value);
  if (!Number.isFinite(num)) return 0;
  return Math.min(100, Math.max(0, num));
}
console.log(clampPercent('150'), clampPercent(42), clampPercent('-3')); // 100 42 0

output:
100 42 0

Split the text, trim each piece and convert it, which keeps stray spaces in the data from turning into NaN.

code:
function parseNumberList(text) {
  if (String(text).trim() === '') return [];
  return text.split(',').map((piece) => Number(piece.trim()));
}
console.log(parseNumberList('1, 2, 3').join('+')); // 1+2+3
console.log(parseNumberList('').length); // 0
console.log(parseNumberList('4, x')); // [ 4, NaN ]

output:
1+2+3
0
[ 4, NaN ]

Let Number do the reading, then check that the original text is not empty and not just spaces, because those read as zero.

code:
function isNumericString(str) {
  if (typeof str !== 'string' || str.trim() === '') return false;
  return Number.isFinite(Number(str));
}
const inputs = ['12', '12px', ' 12 ', '1.5', '', '-3'];
console.log(inputs.map(isNumericString).join(', ')); // true, false, true, true, false, true

output:
true, false, true, true, false, true

Keeping all three versions side by side is the fastest way to see exactly what a piece of loose data turns into.

code:
function describeValue(value) {
  const num = Number(value);
  return {
    raw: value,
    text: String(value),
    number: Number.isFinite(num) ? num : 'NaN',
  };
}
const info = describeValue(' 42 ');
console.log('[' + info.text + ']'); // [ 42 ]
console.log(info.number); // 42
console.log(JSON.stringify(describeValue('abc').number)); // "NaN"

output:
[ 42 ]
42
"NaN"

Convert to text and lowercase first, then check the small list of accepted words. Anything not on a list counts as false.

code:
function parseFlag(raw) {
  const text = String(raw).trim().toLowerCase();
  return ['true', '1', 'yes'].includes(text);
}
console.log(parseFlag('TRUE'), parseFlag('no')); // true false
console.log(['yes', '0', '', null].map((raw) => String(parseFlag(raw))).join(',')); // true,false,false,false
console.log(parseFlag(undefined)); // false

output:
true false
true,false,false,false
false

Check for the two missing values first, then leave real arrays alone so you never end up with a nested array.

code:
function toList(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}
console.log(toList(null).length, toList('a').join(','), toList([1, 2]).join(',')); // 0 a 1,2
console.log(JSON.stringify(toList(toList('x')))); // ["x"]

output:
0 a 1,2
["x"]

Convert both arguments, reject anything that is not finite, and treat a zero divisor as a missing answer rather than Infinity.

code:
function safeDivide(a, b) {
  const top = Number(a);
  const bottom = Number(b);
  if (!Number.isFinite(top) || !Number.isFinite(bottom) || bottom === 0) return null;
  return top / bottom;
}
console.log(safeDivide(10, 4)); // 2.5
console.log(safeDivide(10, 0), safeDivide(10, 'x')); // null null

output:
2.5
null null

String first so a number and a text id behave the same, then padStart fills the front with the character you choose.

code:
function padId(value) {
  return String(value).padStart(5, '0');
}
console.log(padId(42), padId('7'), padId(123456)); // 00042 00007 123456
console.log(padId(42).length, typeof padId(42)); // 5 string

output:
00042 00007 123456
5 string

Multiply by 100, divide by the total, then round for display. Guard the zero total first so the division cannot produce Infinity.

code:
function percentOf(spent, total) {
  const part = Number(spent);
  const whole = Number(total);
  if (!Number.isFinite(part) || !Number.isFinite(whole) || whole === 0) return 0;
  return Number(((part / whole) * 100).toFixed(2));
}
console.log(percentOf('50', 200)); // 25
console.log(percentOf(10, 0)); // 0
console.log(percentOf(1, 3)); // 33.33

output:
25
0
33.33

Double the not operator gives you a real boolean, and wrapping that in a ternary makes the result readable in a log line.

code:
function truthy(value) {
  return !!value ? 'truthy' : 'falsy';
}
const values = [0, '0', '', null, undefined, NaN, 'hello'];
console.log(values.map(truthy).join(', ')); // falsy, truthy, falsy, falsy, falsy, falsy, truthy

output:
falsy, truthy, falsy, falsy, falsy, falsy, truthy

One pass produces all three conversions side by side, which is exactly the table you want when a payload arrives with mixed types.

code:
function convertAll(values) {
  return values.map((value) => ({
    value: String(value),
    number: String(Number(value)),
    bool: String(Boolean(value)),
  }));
}
console.log(JSON.stringify(convertAll([1, '2', null]))); // [{"value":"1","number":"1","bool":"true"},{"value":"2","number":"2","bool":"true"},{"value":"null","number":"0","bool":"false"}]

output:
[{"value":"1","number":"1","bool":"true"},{"value":"2","number":"2","bool":"true"},{"value":"null","number":"0","bool":"false"}]

Number.isFinite is the honest check because it rejects NaN, Infinity and text in one go, so the first bad value is easy to report.

code:
function findBadNumbers(list) {
  for (const value of list) {
    if (!Number.isFinite(Number(value))) return value;
  }
  return 'none';
}
console.log(findBadNumbers(['5', 'x', '7'])); // x
console.log(findBadNumbers(['5', '7'])); // none

output:
x
none

Divide by the unit, then pick the label with a ternary. Keeping the raw number until the last step avoids rounding too early.

code:
function formatBytes(bytes) {
  const num = Number(bytes);
  if (!Number.isFinite(num)) return 'unknown';
  if (num < 1024) return num + ' B';
  if (num < 1024 * 1024) return (num / 1024).toFixed(1) + ' KB';
  return (num / (1024 * 1024)).toFixed(1) + ' MB';
}
console.log(formatBytes(1536)); // 1.5 KB
console.log(formatBytes(1048576)); // 1.0 MB
console.log(formatBytes(512)); // 512 B

output:
1.5 KB
1.0 MB
512 B

Cleaning the text first is often what a form does behind the scenes before it converts the value, so the conversion then succeeds.

code:
function stripSpaces(text) {
  const cleaned = String(text).replace(/\s+/g, '');
  const value = Number(cleaned);
  return Number.isFinite(value) ? value : 'not a number';
}
console.log(stripSpaces('1 2 3')); // 123
console.log(stripSpaces('1 2 x')); // not a number

output:
123
not a number

Convert the input with Number, do the arithmetic, then round for display. The text input is the case that usually breaks.

code:
function toCelsius(fahrenheit) {
  const value = Number(fahrenheit);
  if (!Number.isFinite(value)) return 'bad input';
  return Number((((value - 32) * 5) / 9).toFixed(1));
}
console.log(toCelsius('68')); // 20
console.log(toCelsius(32)); // 0
console.log(toCelsius('abc')); // bad input

output:
20
0
bad input

Filter to the values that convert cleanly, then average only those. The length of the filtered list is the divisor, not the original length.

code:
function averageOfStrings(list) {
  const numbers = list.map(Number).filter(Number.isFinite);
  if (numbers.length === 0) return 0;
  return Number((numbers.reduce((sum, n) => sum + n, 0) / numbers.length).toFixed(2));
}
console.log(averageOfStrings(['10', '20', 'oops', '30'])); // 20
console.log(averageOfStrings([])); // 0

output:
20
0

Wrapping each value in Boolean is the honest way to see the engine's verdict. Counting the true results gives you the truthy count, and the text 'false' is one of them.

code:
function countTruthy(list) {
  return list.filter((value) => Boolean(value)).length;
}
const list = [0, 'false', '', 1, null];
console.log(countTruthy(list)); // 2
console.log(list.map((value) => Boolean(value)).join(',')); // false,true,false,true,false

output:
2
false,true,false,true,false

JSON only understands whole JSON text, so a trailing unit is a hard parse error rather than a quiet NaN.

code:
console.log(JSON.parse(String(42)) + 1); // 43
console.log(Number(JSON.stringify(42)) + 1); // 43
try {
  console.log(JSON.parse('42px'));
} catch (err) {
  console.log(err.constructor.name); // SyntaxError
}

output:
43
43
SyntaxError

Convert both sides before adding, otherwise a single text operand silently turns the whole sum into joined text.

code:
function addValues(a, b) {
  const sum = Number(a) + Number(b);
  return Number.isFinite(sum) ? sum : 'not numbers';
}
console.log(addValues(1, '2')); // 3
console.log(addValues('1', 2)); // 3
console.log(addValues('1', 'x')); // not numbers

output:
3
3
not numbers

Convert the code to a number first so the text version from a query string behaves exactly like the real number.

code:
function toStatusText(code) {
  const value = Number(code);
  if (value === 200) return 'passed';
  if (value === 400) return 'failed';
  return 'error';
}
console.log(toStatusText('200'), toStatusText(400), toStatusText(500)); // passed failed error
console.log(toStatusText('abc')); // error

output:
passed failed error
error

Trim, reject the empty case, then let Number read the rest. Anything that is not finite is invalid rather than quietly zero.

code:
function ageFromInput(raw) {
  const text = String(raw).trim();
  if (text === '') return 0;
  const value = Number(text);
  return Number.isFinite(value) ? value : 'invalid';
}
console.log(ageFromInput('30')); // 30
console.log(ageFromInput('')); // 0
console.log(ageFromInput('thirty')); // invalid

output:
30
0
invalid
